import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.G0y0PQA7.js";const d="/relio/shots/ko/export-image-dialog.png",l="/relio/shots/ko/export-text-mermaid.png",u=JSON.parse('{"title":"내보내기","description":"","frontmatter":{},"headers":[],"relativePath":"features/export.md","filePath":"features/export.md"}'),i={name:"features/export.md"};function n(s,t,g,c,h,m){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="내보내기" tabindex="-1">내보내기 <a class="header-anchor" href="#내보내기" aria-label="Permalink to &quot;내보내기&quot;">​</a></h1><p>Excel·HTML·이미지·사전·번역 사전·테스트 데이터·Java와 DBML·Mermaid·Markdown·모델 JSON 내보내기, 그리고 페이지 설정·인쇄를 설명합니다. DDL은 <a href="/relio/features/ddl">DDL</a> 쪽에 따로 있습니다.</p><p>짧은 소개는 빠른 시작의 <a href="/relio/quick/export#그-밖의-내보내기">DDL 만들기·내보내기</a>에 있습니다.</p><h2 id="내보내기-메뉴" tabindex="-1">내보내기 메뉴 <a class="header-anchor" href="#내보내기-메뉴" aria-label="Permalink to &quot;내보내기 메뉴&quot;">​</a></h2><p>파일 › 내보내기 ▸(캔버스 오른쪽 클릭 › 문서 ▸ › 내보내기 ▸도 같음)에서 고릅니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>만드는 것</th></tr></thead><tbody><tr><td>DDL…</td><td>DB에 실행할 SQL — <a href="/relio/features/ddl">DDL</a></td></tr><tr><td>Excel…</td><td>테이블 정의서(<code>.xlsx</code>)</td></tr><tr><td>HTML…</td><td>인터넷 없이 보는 정적 문서 묶음</td></tr><tr><td>이미지…</td><td>PNG · JPG · BMP · SVG 그림</td></tr><tr><td>사전…</td><td>단어 사전 CSV</td></tr><tr><td>번역 사전…</td><td>물리명·논리명 쌍 파일</td></tr><tr><td>테스트 데이터…</td><td>INSERT SQL · DBUnit 파일</td></tr><tr><td>Java…</td><td>Java 클래스 소스(일반 Java · JPA Entity)</td></tr><tr><td>DBML… · Mermaid… · Markdown 문서… · 모델 JSON…</td><td>다른 도구와 주고받는 글 형식</td></tr></tbody></table><p>공통으로:</p><ul><li>이미 있는 파일에 쓰면 덮어쓸지 묻습니다.</li><li>파일을 만들면 앱 창 오른쪽 아래에 알림이 뜨고, <strong>폴더 열기</strong>를 누르면 탐색기에서 그 파일을 고른 채 폴더가 열립니다.</li><li>문서에 적힌 출력 경로가 문서 폴더 밖을 가리키면 &quot;파일에 저장된 경로가 문서 폴더 밖입니다&quot;라고 알립니다. 남에게 받은 파일이면 경로가 맞는지 확인하세요.</li><li>경고가 있으면 개수를 알리고 문제 목록에 남깁니다. 오래 걸리는 내보내기는 진행 창의 <strong>취소</strong>로 멈출 수 있습니다.</li></ul><h2 id="excel" tabindex="-1">Excel <a class="header-anchor" href="#excel" aria-label="Permalink to &quot;Excel&quot;">​</a></h2><ul><li><strong>템플릿</strong> — <strong>내장</strong>(한국어 — 테이블 정의서 (default_ko) · 영어 (default_en) · 일본어 (default_ja) · 중국어 (default_zh)), <strong>파일</strong>(직접 고른 템플릿), 또는 환경 설정 › Excel 템플릿에 등록한 템플릿.</li><li>사용자 템플릿은 words·loops 시트와 템플릿 시트가 있는 <code>.xlsx</code> 또는 ERMaster <code>.xls</code>입니다. 출력은 늘 <code>.xlsx</code>이고, <code>.xls</code>를 고르면 <code>.xlsx</code>로 바꿔 씁니다.</li><li><strong>카테고리</strong> — 전체 또는 카테고리 하나.</li><li><strong>다이어그램 그림 넣기</strong> · <strong>논리명을 시트 이름으로</strong>.</li><li>테이블·인덱스 등은 템플릿 시트를 복사해 만들고, 시트 이름은 31자 안으로 줄이며 겹치면 (1), (2)…를 붙입니다.</li></ul><p>내장 템플릿을 고쳐 쓰려면 도구 › 환경 설정 › Excel 템플릿에서 **파일로 저장…**한 뒤 고쳐서 사용자 템플릿으로 등록합니다. <a href="/relio/features/preferences#excel-템플릿">환경 설정 › Excel 템플릿</a></p><h2 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h2><p><strong>출력 폴더</strong>를 고르고 <strong>다이어그램 이미지 포함</strong> · <strong>카테고리 이미지 포함</strong> · **저장한 뒤 열기 (index.html)**를 정합니다. 프레임 없는 정적 HTML 묶음이라 파일을 그대로 열어 볼 수 있고 인터넷에 접속하지 않습니다. 그림·테이블·컬럼·인덱스가 들어갑니다.</p><h2 id="이미지" tabindex="-1">이미지 <a class="header-anchor" href="#이미지" aria-label="Permalink to &quot;이미지&quot;">​</a></h2><ul><li>형식은 출력 파일의 확장자로 정합니다(PNG·JPG·BMP·SVG).</li><li>그림을 감싸는 영역에 사방 10px 여백, 배율 100%로 그립니다. 한 변이 16,384px를 넘으면 줄이고 알립니다.</li><li>**카테고리별 이미지도 출력 (표시 중인 카테고리)**를 켜면 카테고리마다 그림을 따로 만듭니다. <strong>카테고리 폴더</strong>를 비우면 출력 파일 옆 <code>categories</code> 폴더에 둡니다.</li><li><strong>저장한 뒤 파일 열기</strong>.</li></ul><p>찾기·선택 강조는 그림에 들어가지 않고, 어두운 테마에서도 늘 밝은 색으로 그립니다.</p><figure class="shot" data-scene="export-image-dialog"><img src="'+d+'" alt="이미지 내보내기 창 — 출력 파일과 카테고리별 이미지 옵션" loading="lazy"><figcaption>이미지 내보내기 창 — 출력 파일과 카테고리별 이미지 옵션</figcaption></figure><h2 id="사전" tabindex="-1">사전 <a class="header-anchor" href="#사전" aria-label="Permalink to &quot;사전&quot;">​</a></h2><p><strong>사전 내보내기 (CSV)</strong> — 단어 사전을 CSV로 냅니다. 열은 물리명, 논리명, 형식, 설명입니다. <strong>UTF-8 BOM 붙이기</strong>를 켜면 Excel에서 바로 열 때 한글이 깨지지 않습니다.</p><h2 id="번역-사전" tabindex="-1">번역 사전 <a class="header-anchor" href="#번역-사전" aria-label="Permalink to &quot;번역 사전&quot;">​</a></h2><p><strong>번역 사전 내보내기</strong> — 모델의 물리명·논리명 쌍을 번역 사전 파일(UTF-8, 한 줄에 <code>물리명,논리명</code>)로 냅니다. <strong>사전 이름</strong>과 <strong>저장 위치</strong>를 정하고(확장자가 없으면 <code>.txt</code>), 미리보기로 몇 개가 들어가는지 봅니다. 넣지 않는 항목이 있으면 그 수와 이유를 보여 줍니다. 만든 사전은 DB에서 가져올 때 논리명을 채우는 데 씁니다.</p><h2 id="테스트-데이터" tabindex="-1">테스트 데이터 <a class="header-anchor" href="#테스트-데이터" aria-label="Permalink to &quot;테스트 데이터&quot;">​</a></h2><p>먼저 모델 › 테스트 데이터…에서 데이터를 만들어 둡니다. <a href="/relio/features/model#테스트-데이터">모델 메뉴 › 테스트 데이터</a></p><ul><li><strong>내보낼 테스트 데이터</strong>를 고릅니다.</li><li><strong>형식</strong> — SQL (INSERT 문) · DBUnit XML · DBUnit Flat XML · DBUnit Excel (.xlsx).</li><li>**테스트 데이터 하나에 파일 하나 (이름.확장자)**를 켜면 데이터마다 파일을 따로 만듭니다.</li></ul><p>작은따옴표·빈 값이 든 값도 SQL이 깨지지 않게 씁니다.</p><h2 id="java" tabindex="-1">Java <a class="header-anchor" href="#java" aria-label="Permalink to &quot;Java&quot;">​</a></h2><table tabindex="0"><thead><tr><th>칸</th><th>설명</th></tr></thead><tbody><tr><td>출력 폴더</td><td>패키지 폴더는 그 아래에 만듭니다.</td></tr><tr><td>패키지 이름</td><td>예: <code>com.example.model</code>. Java 규칙에 맞지 않으면 알립니다.</td></tr><tr><td>클래스 이름 접미사</td><td>예: <code>Entity</code>. 비우면 붙이지 않습니다.</td></tr><tr><td>파일 인코딩</td><td></td></tr><tr><td>형식</td><td><strong>일반 Java</strong> 또는 <strong>JPA Entity</strong>(<code>@Entity</code> 클래스)</td></tr><tr><td>Hibernate 매핑 파일 출력 (.hbm.xml)</td><td>일반 Java일 때만. JPA Entity 형식에서는 쓰지 않습니다.</td></tr></tbody></table><p><strong>JPA 옵션</strong>(형식이 JPA Entity일 때):</p><ul><li><strong>javax.persistence 쓰기 (끄면 jakarta.persistence)</strong></li><li><strong>날짜를 java.util.Date로 (끄면 java.time)</strong></li><li><strong>부모에 자식 목록 필드 넣기 (@OneToMany)</strong></li><li><strong>외래 키를 객체 대신 값 필드로</strong></li></ul><h2 id="글-형식-내보내기-dbml·mermaid·markdown·모델-json" tabindex="-1">글 형식 내보내기 (DBML·Mermaid·Markdown·모델 JSON) <a class="header-anchor" href="#글-형식-내보내기-dbml·mermaid·markdown·모델-json" aria-label="Permalink to &quot;글 형식 내보내기 (DBML·Mermaid·Markdown·모델 JSON)&quot;">​</a></h2><p>공통 칸:</p><ul><li><strong>범위</strong> — 전체 · 카테고리 · 선택한 테이블(캔버스에서 먼저 선택).</li><li><strong>출력 파일</strong> · <strong>인코딩</strong> · <strong>줄바꿈을 CRLF로 쓰기 (Windows)</strong>.</li><li><strong>클립보드로 복사</strong> — 파일 없이 바로 붙여 넣습니다(DBML · Mermaid · Markdown).</li><li>설정은 이 PC에 파일별로 기억합니다. 문서(<code>.erm</code>)는 바뀌지 않으므로 내보내도 &quot;변경됨&quot;이 되지 않습니다.</li></ul><table tabindex="0"><thead><tr><th>형식</th><th>무엇</th><th>형식 옵션</th></tr></thead><tbody><tr><td>DBML</td><td>dbdiagram.io 등에서 쓰는 글 형식</td><td>컬럼 그룹을 TablePartial로 쓰기 · 노트를 스티키 노트로 쓰기</td></tr><tr><td>Mermaid</td><td>GitHub·노션 등이 그림으로 보여 주는 <code>erDiagram</code></td><td>논리명을 별칭으로 쓰기 · mermaid 코드 울타리로 감싸기 · 카테고리마다 파일 따로 만들기</td></tr><tr><td>Markdown 문서</td><td>목차·Mermaid 그림·테이블마다 컬럼·외래 키·인덱스 표가 있는 정의서</td><td>Mermaid 그림 넣기 · 뷰 넣기 · 인덱스·고유 키 표 넣기 · 테이블 표만 (제목·목차·그림 없이) · 카테고리별로 묶기</td></tr><tr><td>모델 JSON</td><td>모델 전체를 JSON으로 — 다른 도구와 연결할 때</td><td>이미지 넣기 (Base64) · 변경 내역 넣기 · 배치(위치·크기·색) 빼기 · 만든 시각 넣기</td></tr></tbody></table><p>모델 JSON의 구조를 설명하는 JSON Schema는 명령줄 <code>relio export json --print-schema</code>로 얻습니다. <a href="/relio/features/cli#relio-export">명령줄</a></p><figure class="shot" data-scene="export-text-mermaid"><img src="'+l+'" alt="Mermaid 내보내기 창 — 범위와 형식 옵션, 클립보드로 복사" loading="lazy"><figcaption>Mermaid 내보내기 창 — 범위와 형식 옵션, 클립보드로 복사</figcaption></figure><h2 id="인쇄" tabindex="-1">인쇄 <a class="header-anchor" href="#인쇄" aria-label="Permalink to &quot;인쇄&quot;">​</a></h2><ul><li><strong>파일 › 페이지 설정…</strong> — <strong>방향</strong>(가로·세로, 기본 가로), <strong>배율 %</strong>, <strong>용지 크기</strong>(기본 A4), 여백 <strong>위</strong> · <strong>왼쪽</strong> · <strong>오른쪽</strong> · <strong>아래</strong>(cm).</li><li><strong>파일 › 인쇄…</strong>(<kbd>Ctrl</kbd>+<kbd>P</kbd>) — 인쇄 미리보기에서 지금 화면(전체 또는 카테고리)의 쪽 나눔과 쪽 수를 보고, **인쇄…**로 운영체제 인쇄 창에 보냅니다. 미리보기에서 **페이지 설정…**을 바로 열 수도 있습니다.</li><li>인쇄는 페이지 설정의 배율로 그려 왼쪽에서 오른쪽, 위에서 아래 순으로 여러 쪽에 나눕니다. 격자 없이 흰 바탕입니다.</li><li>캔버스에는 한 쪽 크기마다 연회색 선으로 쪽 경계가 보입니다(내보내기·인쇄에는 그리지 않음).</li></ul>',37)])])}const x=r(i,[["render",n]]);export{u as __pageData,x as default};
